,r=55,x=6600,f=6,sd=0,h=4,o={"Take the Bag of Horrors to Eva Sarkhoff on Caer Darrow. Provided item: Krastinov's Bag of Horrors UNUSED"},p={5382},nx={5384}},{i=5384,n="Kirtonos the Herald",l=60,r=55,x=8300,f=6,sd=3,h=5,s={{k="n",i=11216,n="Eva Sarkhoff",z=28,c={[28]={{70.2,73.7}}}}},e={{k="n",i=11216,n="Eva Sarkhoff",z=28,c={[28]={{70.2,73.7}}}}},o={"Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.","","Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.",""},ot={"Kirtonos the Herald"},p={5515},nx={5461}},{i=5515,n="Krastinov's Bag of Horrors",l=60,r=55,x=6600,f=6,sd=3,h=5,s={{k="n",i=11216,n="Eva Sarkhoff",z=28,c={[28]={{70.2,73.7}}}}},e={{k="n",i=11216,n="Eva Sarkhoff",z=28,c={[28]={{70.2,73.7}}}}},o={"Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff."},ot={"Krastinov's Bag of Horrors"},p={5382},nx={5384}},{i=4771,n="Dawn's Gambit",l=60,r=57,x=9950,f=6,sd=3,h=2,s={{k="n",i=11035,n="Betina Bigglezink",z=139,c={[139]={{71.7,49.9}}}}},e={{k="n",i=11035,n="Betina Bigglezink",z=139,c={[139]={{71.7,49.9}}}}},o={"Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink."},ot={"Vectus"},p={5531}},{i=5466,n="The Lich, Ras Frostwhisper",l=60,r=57,x=9950,f=6,sd=3,h=5,s={{k="n",i=11286,n="Magistrate Marduke",z=28,c={[28]={{70.6,74.1}}}}},e={{k="n",i=11286,n="Magistrate Marduke",z=28,c={[28]={{70.6,74.1}}}}},o={"Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke."},ot={"Human Head of Ras Frostwhisper"},p={5465}},{i=5531,n="Betina Bigglezink",l=60,r=57,x=1650,f=6,sd=3,h=2,s={{k="n"